import React from 'react';
import { configure, addDecorator } from '@storybook/react';
import 'bootstrap/dist/css/bootstrap.min.css';

addDecorator((storyFn) => (
  <div
    style={{
      padding: '1.5rem',
      minHeight: '100vh',
    }}
  >
    {storyFn()}
  </div>
));

function loadStories() {
  /**
   * Loads everything in ../app/components with
   * suffix .stories.js
   */
  const req = require.context('../src/components', true, /\.stories\.js$/);
  req.keys().forEach((filename) => req(filename));
}

configure(loadStories, module);

const path = require('path');

module.exports = (plop) => {
  // controller generator
  plop.setGenerator('component', {
    description: 'Create a React component',
    prompts: [
      {
        type: 'input',
        name: 'name',
        message: 'Component name:',
      },
    ],
    actions: [
      {
        type: 'add',
        path: path.resolve(
          __dirname,
          '../../src/components/{{properCase name}}/index.js',
        ),
        templateFile: path.resolve(__dirname, './templates/index.js.hbs'),
      },
      {
        type: 'add',
        path: path.resolve(
          __dirname,
          '../../src/components/{{properCase name}}/index.stories.js',
        ),
        templateFile: path.resolve(
          __dirname,
          './templates/index.stories.js.hbs',
        ),
      },
    ],
  });
};

import React from 'react';
import 'bootstrap/dist/css/bootstrap.min.css';

export default ({ children }) => {
  return <div>{children}</div>;
};

import React from 'react';
import { storiesOf } from '@storybook/react';
import Header from './index';

storiesOf('Header', module).add('Normal', () => {
  return <Header />;
});

import React from 'react';
import styled from 'styled-components';

const Header = () => {
  return <HeaderWrapper>Hello</HeaderWrapper>;
};

export default Header;

const HeaderWrapper = styled.div`
  background-color: #333;
  padding: 1rem;
  color: white;
`;
